.darma-loader-tw-grid-fade { display: grid; grid-template-columns: repeat(3, 1fr); gap: calc(var(--loader-size, 60px) * .07); width: var(--loader-size, 60px); height: var(--loader-size, 60px); }
.darma-loader-tw-grid-fade span { border-radius: calc(var(--loader-size, 60px) * .06); background: var(--loader-color, #6366f1); animation: darma-loader-tw-grid-fade-twScaleFade calc(var(--loader-speed, 1s) * 1.3) ease-in-out infinite; }
.darma-loader-tw-grid-fade span:nth-child(2), .darma-loader-tw-grid-fade span:nth-child(4) { animation-delay: calc(var(--loader-speed, 1s) * .1); }
.darma-loader-tw-grid-fade span:nth-child(3), .darma-loader-tw-grid-fade span:nth-child(5), .darma-loader-tw-grid-fade span:nth-child(7) { animation-delay: calc(var(--loader-speed, 1s) * .2); }
.darma-loader-tw-grid-fade span:nth-child(6), .darma-loader-tw-grid-fade span:nth-child(8) { animation-delay: calc(var(--loader-speed, 1s) * .3); }
.darma-loader-tw-grid-fade span:nth-child(9) { animation-delay: calc(var(--loader-speed, 1s) * .4); }
@keyframes darma-loader-tw-grid-fade-twScaleFade { 0%, 70%, 100% { transform: scale(.6); opacity: .3; } 35% { transform: scale(1); opacity: 1; } }

